//! Test vectors shared by the modules that consume them.
//!
//! The instance documents published with content-09, and the message IDs published alongside them.
//! Both the codec tests and the message ID tests read this one table, so a vector cannot be
//! corrected in one place and left stale in another.

/// The 14 mimiContent instance documents from the content-09 examples, as encoded CBOR. Coverage:
/// SinglePart (text/markdown, text/plain, html), NullPart (delete, unlike), ExternalPart
/// (attachment, conferencing), recursive MultiPart (multipart-1/2/3), every disposition in the
/// suite, extensions 1 and 2, set and null replaces, expires and inReplyTo, emoji and unicode
/// content. A fifteenth published document, implied-original, has a different structure and is
/// asserted rejected by the codec tests rather than listed here.
pub(crate) const OFFICIAL_VECTORS: &[(&str, &str)] = &[
    ("attachment", ""),
    ("conferencing", ""),
    ("delete", ""),
    ("edit", ""),
    ("expiring", ""),
    ("mention", ""),
    ("mention-html", ""),
    ("multipart-1", ""),
    ("multipart-2", ""),
    ("multipart-3", ""),
    ("original", ""),
    ("reaction", ""),
    ("reply", ""),
    ("unlike", ""),
];

