/// The encoded document for a named example.
///
/// Panics when the name is absent, so renaming or dropping a vector fails the tests that join
/// against it rather than silently reducing their coverage.
pub(crate) fn official_vector(name: &str) -> &'static str {
    OFFICIAL_VECTORS
        .iter()
        .find(|(vector_name, _)| *vector_name == name)
        .map(|(_, hex)| *hex)
        .unwrap_or_else(|| panic!("no official vector named {name}"))
}

/// Decode a hex string from the tables above.
pub(crate) fn decode_hex(hex: &str) -> Vec<u8> {
    assert!(hex.len().is_multiple_of(2), "hex string has an odd length");
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("vector is valid hex"))
        .collect()
}
